<script lang="ts">import '$lib/design/tokens.css'; import '$lib/components/commerce/store.css'; import { announceCart, cartRequest, type ClientCart } from '$lib/client/cart'; import type { PageData } from './$types'; let { data }: { data: PageData } = $props(); let cart = $state<ClientCart | null>(null); $effect(() => { if (cart === null) cart = data.cart as ClientCart | null; }); let busy = $state(''); let message = $state(''); function price(p: { price: string; currency_code: string; currency_minor_unit: number }) { const n = Number(p.price) / 10 ** p.currency_minor_unit; return `${new Intl.NumberFormat('fa-IR').format(p.currency_code === 'IRR' ? n / 10 : n)} تومان`; } async function change(key: string, quantity: number) { busy = key; message = ''; try { cart = await cartRequest({ action: 'update', key, quantity }); announceCart(cart); } catch (e) { message = e instanceof Error ? e.message : 'تغییر سبد ناموفق بود.'; } finally { busy = ''; } } async function remove(key: string) { busy = key; message = ''; try { cart = await cartRequest({ action: 'remove', key }); announceCart(cart); } catch (e) { message = e instanceof Error ? e.message : 'حذف کالا ناموفق بود.'; } finally { busy = ''; } }</script>
<svelte:head><title>سبد خرید | اینکورا</title><meta name="robots" content="noindex,nofollow" /></svelte:head><div class="inkora-theme inkora-store" dir="rtl"><header class="store-header"><div class="store-container store-header-inner"><a class="store-brand" href="/"><img src="/assets/brand/inkora-wordmark-temporary.svg" alt="اینکورا؛ نوشتار موقت برند" /></a><nav class="store-nav" aria-label="ناوبری"><a href="/shop">فروشگاه</a><a href="/account">حساب</a></nav></div></header><main class="store-container store-main"><header class="store-heading"><h1>سبد خرید</h1></header>{#if data.status === 'error'}<p role="alert">سبد خرید به WooCommerce متصل نشد. دوباره تلاش کنید.</p>{:else if !cart?.items?.length}<div class="store-card product-copy"><h2>سبد خرید خالی است</h2><a class="button primary" href="/shop">مشاهده فروشگاه</a></div>{:else}<div class="cart-layout"><section class="store-card" aria-label="اقلام سبد">{#each cart.items as item}<article class="cart-item"><div>{#if item.images[0]}<img src={item.images[0].thumbnail} alt={item.images[0].alt || `تصویر ${item.name}`} />{:else}<div class="cart-placeholder">بدون تصویر</div>{/if}</div><div><h2>{item.name}</h2><p>{price(item.totals)}</p><div class="quantity"><button aria-label={`کاهش تعداد ${item.name}`} disabled={busy === item.key || item.quantity <= item.quantity_limits.minimum} onclick={() => change(item.key, item.quantity - 1)}>−</button><span>{item.quantity}</span><button aria-label={`افزایش تعداد ${item.name}`} disabled={busy === item.key || item.quantity >= item.quantity_limits.maximum} onclick={() => change(item.key, item.quantity + 1)}>+</button></div></div><button class="button" disabled={busy === item.key} onclick={() => remove(item.key)}>حذف</button></article>{/each}</section><aside class="store-card cart-summary"><h2>خلاصه سفارش</h2><div class="totals"><span>جمع کالاها</span><strong>{price(cart.totals)}</strong></div>{#if cart.totals.total_shipping !== null}<div class="totals"><span>ارسال</span><span>طبق محاسبه ووکامرس</span></div>{/if}<a class="button primary" href="/checkout">ادامه به تسویه</a>{#if message}<p role="alert" class="notice">{message}</p>{/if}</aside></div>{/if}</main></div>
